#pragma once
#include <array>
#include <string>

#include "core/Types.hpp"
#include "formats/Spr.hpp"  // SprPalColor

namespace uaro {

// The clothes-dye palettes (data/palette/몸/...) were made for the uaRO body sprites, but BornRok's 1k/4k
// sprite.zip carries a newer copy of those bodies whose palette is ordered differently: a dye palette applied
// as-is paints skin and outline too. A remap gives, per sprite.zip body, the uaRO palette index each of its
// indices stands for, so the dye is applied as eff[i] = dye[map[i]] and the body shows uaRO.exe's colours.
// Generated by tools/gen_body_pal_remap.py into BodyPalRemapTable.cpp (re-run it when sprite.zip changes).
struct BodyPalRemap {
    const char* body;        // body sprite name, CP949 (data/sprite/인간족/몸통/<sex>/<body>_<sex>.spr)
    bool male;               // sex folder 남 (true) / 여 (false)
    u64 paletteFingerprint;  // sprPaletteFingerprint of the sprite.zip body the map was built from
    u8 map[256];             // sprite.zip palette index -> uaRO body palette index (map[0] = 0)
};

extern const BodyPalRemap kBodyPalRemaps[];
extern const usize kBodyPalRemapCount;

// FNV-1a 64 over the R, G, B bytes of a sprite's embedded palette: tells the exact sprite.zip body a map was
// built from (the generator hashes the same 768 bytes), so a changed body is never remapped by a stale map.
inline u64 sprPaletteFingerprint(const std::array<SprPalColor, 256>& pal) {
    u64 h = 0xcbf29ce484222325ULL;
    for (const SprPalColor& c : pal)
        for (const u8 v : {c.r, c.g, c.b}) {
            h ^= v;
            h *= 0x100000001b3ULL;
        }
    return h;
}

// The remap for this body sprite (name as in jobSpriteName / ridingBodyName), or nullptr: no remap needed
// (the body is the uaRO original) or the loaded sprite is not the one the map was built from.
inline const BodyPalRemap* findBodyPalRemap(const std::string& body, bool male, u64 fingerprint) {
    for (usize i = 0; i < kBodyPalRemapCount; ++i) {
        const BodyPalRemap& r = kBodyPalRemaps[i];
        if (r.male == male && r.paletteFingerprint == fingerprint && body == r.body) return &r;
    }
    return nullptr;
}

// eff[i] = dye[map[i]] for i = 1..255; index 0 (transparent) keeps the dye's own entry.
inline std::array<SprPalColor, 256> remapPalette(const std::array<SprPalColor, 256>& dye, const u8 (&map)[256]) {
    std::array<SprPalColor, 256> eff = dye;
    for (usize i = 1; i < 256; ++i) eff[i] = dye[map[i]];
    return eff;
}

} // namespace uaro
